{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Aggressive 4th-Down Decisions",
      "recommendation": "Go for it on 4th-and-1 to 3 yards whenever past the opponent's 45-yard line, and occasionally from own territory in plus situations, following win-probability model recommendations.",
      "rationale": "Models show punting yields similar expected points as surrendering possession, while converting retains scoring opportunities and substantially raises win probability.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.5,
          "interval_95_low": -0.2,
          "interval_95_high": 1.2,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Effect should be roughly symmetric around a small positive mode, with thin tails because the upside is capped by extra possessions and downside limited by field-position value."
        },
        "parameters": {
          "mu": 0.5,
          "sigma": 0.357,
          "conversion_note": "sigma = (1.2 - (-0.2)) / 3.92 ≈ 1.4 / 3.92 = 0.357"
        },
        "consistency_check": "Most plausible 0.5 lies inside [-0.2, 1.2]; normal support is all reals, covering signed values."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Early-Down Play-Action Passes",
      "recommendation": "Use play-action passing on 1st and 2nd down regardless of run-game success, exploiting linebackers' run-fits to open intermediate routes.",
      "rationale": "Play-action consistently yields higher yards per attempt and lower interception rate than straight dropbacks, even when the run game is ineffective; it directly increases scoring.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.7,
          "interval_95_low": 0.1,
          "interval_95_high": 1.3,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The effect is likely symmetric with little chance of extreme values; large upside would require defensive meltdowns, large downside would mean extreme interception luck, both improbable."
        },
        "parameters": {
          "mu": 0.7,
          "sigma": 0.306,
          "conversion_note": "sigma = (1.3 - 0.1) / 3.92 ≈ 1.2 / 3.92 = 0.306"
        },
        "consistency_check": "Most plausible 0.7 is inside [0.1, 1.3]; normal covers signed values."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Two-High Safety Shells",
      "recommendation": "Base out of two-high safety coverage (Cover 2, Quarters) to limit explosive passes and force offenses into long, methodical drives.",
      "rationale": "Data shows explosive plays are highly correlated with opponent scoring; two-high looks reduce deep completions without significantly increasing underneath efficiency, lowering opponent points per drive.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.3,
          "interval_95_low": -0.3,
          "interval_95_high": 0.9,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The net benefit is likely small and symmetric; large deviations would require a league-wide shift in offensive scheme, which is unlikely in the short term."
        },
        "parameters": {
          "mu": 0.3,
          "sigma": 0.306,
          "conversion_note": "sigma = (0.9 - (-0.3)) / 3.92 ≈ 1.2 / 3.92 = 0.306"
        },
        "consistency_check": "Most plausible 0.3 inside [-0.3, 0.9]; normal support covers signed values."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Momentum-Stopping Timeouts",
      "recommendation": "Use timeouts on defense during opponent's critical 3rd-down plays to disrupt rhythm and force a mental reset, even at the expense of end-of-half clock management.",
      "rationale": "Psychological disruption can lower conversion rates on key downs, leading to additional stops and a possession edge; this relies on coaching intuition about player psychology because public analytics on icing/timeout effect is sparse and mixed.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.2,
          "interval_95_low": -0.5,
          "interval_95_high": 0.9,
          "shape": "right_skewed",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Right skew captures a small chance of a large positive payoff if timeouts repeatedly cause failed conversions, while downside is bounded by lost clock value but can be significant."
        },
        "parameters": {
          "xi": -0.1,
          "omega": 0.5,
          "alpha": 2.0,
          "conversion_note": "α=2.0 gives right skew; ξ and ω fitted numerically so mode ≈0.2 and central 95% mass ≈[-0.5, 0.9] (approximate)."
        },
        "consistency_check": "Mode ~0.2 inside interval; skew_normal has unbounded real support, covering signed values."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Permanent No-Huddle Tempo",
      "recommendation": "Run the offense at a consistently fast pace (no-huddle, quick snaps) throughout the game, not just in two-minute drills, to wear down defenses and prevent substitutions.",
      "rationale": "Wearing down opponents leads to more explosive plays later in halves and can induce defensive penalties; public analytics is mixed on the net effect because faster drives also give the opponent more possessions, so this relies on a belief in fatigue and psychological pressure.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.8,
          "interval_95_low": -0.3,
          "interval_95_high": 1.9,
          "shape": "right_skewed",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "If the strategy works, the upside could be large as defenses tire and break down; downside is limited but non-trivial if it leads to quick three-and-outs and exposes own defense."
        },
        "parameters": {
          "xi": 0.5,
          "omega": 0.6,
          "alpha": 2.0,
          "conversion_note": "α=2.0; ξ and ω fitted numerically to give mode ≈0.8 and 95% interval ≈[-0.3, 1.9]."
        },
        "consistency_check": "Mode ~0.8 inside interval; skew_normal support covers signed values."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Amoeba Pressure Defense",
      "recommendation": "Deploy a versatile 3-4 front with multiple stand-up defenders moving pre-snap and frequent overload blitzes, aiming to confuse the offensive line and force hurried decisions.",
      "rationale": "Chaotic pressure creates negative plays (sacks, interceptions) that strongly correlate with winning; public analytics is mixed because ultra-aggressive blitzing can also yield big gains, but this intuition accepts high variance as beneficial for a .500 team.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.4,
          "interval_95_low": -1.0,
          "interval_95_high": 1.8,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "High variance and heavy tails reflect the possibility of either a game-breaking turnover-fest or repeated coverage busts; symmetric around a small positive mode."
        },
        "parameters": {
          "nu": 4.0,
          "mu": 0.4,
          "sigma": 0.5036,
          "conversion_note": "ν=4 (heavy tails); t_{0.975,4} ≈ 2.78; sigma = (1.8 - (-1.0)) / (2 × 2.78) ≈ 2.8 / 5.56 = 0.5036"
        },
        "consistency_check": "μ=0.4 is inside [-1.0, 1.8]; student_t support covers all reals, signed values included."
      }
    }
  ],
  "plot_script": "import numpy as np\nimport matplotlib.pyplot as plt\nfrom scipy.stats import norm, t, skewnorm\n\nstrategies = [\n    {\n        'title': 'Aggressive 4th-Down Decisions',\n        'family': 'normal',\n        'params': {'mu': 0.5, 'sigma': 0.357},\n        'most_plausible': 0.5\n    },\n    {\n        'title': 'Early-Down Play-Action Passes',\n        'family': 'normal',\n        'params': {'mu': 0.7, 'sigma': 0.306},\n        'most_plausible': 0.7\n    },\n    {\n        'title': 'Two-High Safety Shells',\n        'family': 'normal',\n        'params': {'mu': 0.3, 'sigma': 0.306},\n        'most_plausible': 0.3\n    },\n    {\n        'title': 'Momentum-Stopping Timeouts',\n        'family': 'skew_normal',\n        'params': {'xi': -0.1, 'omega': 0.5, 'alpha': 2.0},\n        'most_plausible': 0.2\n    },\n    {\n        'title': 'Permanent No-Huddle Tempo',\n        'family': 'skew_normal',\n        'params': {'xi': 0.5, 'omega': 0.6, 'alpha': 2.0},\n        'most_plausible': 0.8\n    },\n    {\n        'title': 'Amoeba Pressure Defense',\n        'family': 'student_t',\n        'params': {'nu': 4.0, 'mu': 0.4, 'sigma': 0.5036},\n        'most_plausible': 0.4\n    }\n]\n\nx = np.linspace(-3, 4, 1000)\nfig, axes = plt.subplots(2, 3, figsize=(15, 8))\naxes = axes.flatten()\n\nfor ax, strat in zip(axes, strategies):\n    if strat['family'] == 'normal':\n        mu = strat['params']['mu']\n        sigma = strat['params']['sigma']\n        dist = norm(mu, sigma)\n        pdf = dist.pdf(x)\n        low = dist.ppf(0.025)\n        high = dist.ppf(0.975)\n        label = f'Normal(μ={mu:.3f}, σ={sigma:.3f})'\n    elif strat['family'] == 'student_t':\n        nu = strat['params']['nu']\n        mu = strat['params']['mu']\n        sigma = strat['params']['sigma']\n        dist = t(df=nu, loc=mu, scale=sigma)\n        pdf = dist.pdf(x)\n        low = dist.ppf(0.025)\n        high = dist.ppf(0.975)\n        label = f't(ν={nu}, μ={mu:.3f}, σ={sigma:.3f})'\n    elif strat['family'] == 'skew_normal':\n        xi = strat['params']['xi']\n        omega = strat['params']['omega']\n        alpha = strat['params']['alpha']\n        dist = skewnorm(loc=xi, scale=omega, a=alpha)\n        pdf = dist.pdf(x)\n        low = dist.ppf(0.025)\n        high = dist.ppf(0.975)\n        label = f'SkewNormal(ξ={xi:.3f}, ω={omega:.3f}, α={alpha:.1f})'\n    \n    ax.plot(x, pdf, 'k-', linewidth=2)\n    ax.fill_between(x, pdf, where=(x >= low) & (x <= high), color='skyblue', alpha=0.4, label='95% interval')\n    ax.axvline(strat['most_plausible'], color='red', linestyle='--', label=f'Most plausible = {strat[\"most_plausible\"]}')\n    ax.set_title(strat['title'], fontsize=11)\n    ax.set_xlabel('Change in own scoring margin (points)')\n    ax.legend(loc='upper right', fontsize=8)\n    print(f'{strat[\"title\"]}: {label}')\n\nplt.tight_layout()\nplt.show()\n"
}
